sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float debris;
float2 hash22(float2 p) {
    float3 q = fract(float3(p.xyx) * float3(0.1031, 0.1030, 0.0973));
    q += dot(q, q.yzx + 33.33);
    return fract((q.xx + q.yz) * q.zy);
}
half4 main(float2 coord) {
    if (coord.x < 0.0 || coord.y < 0.0 || coord.x > size.x || coord.y > size.y) return image.eval(coord);
    float s = max(min(size.x, size.y), 1.0);
    float k = clamp(debris, 1.0, 30.0);
    float n = floor(4.0 + k * 0.75);
    float scale = n / 6.2831853;
    float2 c = float2(0.47, 0.44) * size;
    float2 d = coord - c;
    float r = length(d);
    float r0 = 0.03 * s;
    float2 w = float2(log(r + r0) * scale, (atan(d.y, d.x) / 6.2831853 + 0.5) * n);
    float2 cell = floor(w);
    float2 f = w - cell;
    float best = 8.0;
    float2 nearest = float2(0.0);
    float2 piece = float2(0.0);
    float2 seat = float2(0.0);
    for (int j = -1; j <= 1; j++) {
        for (int i = -1; i <= 1; i++) {
            float2 g = float2(float(i), float(j));
            float2 id = float2(cell.x + g.x, mod(cell.y + g.y, n));
            float2 o = 0.15 + 0.7 * hash22(id + 3.17);
            float2 v = g + o - f;
            float dd = dot(v, v);
            if (dd < best) { best = dd; nearest = v; piece = id; seat = cell + g + o; }
        }
    }
    float edge = 8.0;
    for (int j = -2; j <= 2; j++) {
        for (int i = -2; i <= 2; i++) {
            float2 g = float2(float(i), float(j));
            float2 id = float2(cell.x + g.x, mod(cell.y + g.y, n));
            float2 v = g + 0.15 + 0.7 * hash22(id + 3.17) - f;
            float2 diff = v - nearest;
            if (dot(diff, diff) > 0.00001) edge = min(edge, dot(0.5 * (nearest + v), normalize(diff)));
        }
    }
    float rs = max(exp(seat.x / scale) - r0, 0.0);
    float ang = (seat.y / n - 0.5) * 6.2831853;
    float2 way = float2(cos(ang), sin(ang));
    float2 centre = c + rs * way;
    float2 h = hash22(piece + 17.31);
    float2 h2 = hash22(piece + 41.73);
    float amp = s * (0.004 + 0.0012 * k);
    float2 shift = way * amp * (0.4 + 0.8 * h.x) + float2(-way.y, way.x) * amp * (h.y - 0.5);
    float turn = (h2.x - 0.5) * 2.0 * radians(0.8 + 0.15 * k);
    float2 q = coord - centre - shift;
    float cs = cos(turn), sn = sin(turn);
    float2 from = centre + float2(cs * q.x + sn * q.y, -sn * q.x + cs * q.y);
    half4 col = image.eval(clamp(from, float2(0.5), size - 0.5));
    float3 rgb = float3(col.rgb) * (1.0 + (h2.y - 0.5) * 0.16);
    float px = edge * (r + r0) / scale;
    float lw = max(1.2, s / 600.0);
    float core = 1.0 - smoothstep(lw * 0.35, lw, px);
    float rim = (1.0 - smoothstep(lw, lw * 3.0, px)) * (1.0 - core);
    rgb = mix(rgb * (1.0 - 0.3 * rim), float3(0.93) * float(col.a), 0.8 * core);
    return half4(half3(min(rgb, float3(col.a))), col.a);
}
